printf " \033[38;2;204;116;225m/   \033[38;2;208;111;217m/ \033[38;2;210;108;212m/\033[38;2;211;107;210m_\033[38;2;211;105;208m/ \033[38;2;213;103;204m/ \033[38;2;215;100;200m/\033[38;2;216;99;198m_\033[38;2;217;98;196m/ \033[38;2;219;95;192m/   \033[38;2;223;90;183m/ \033[38;2;224;88;179m/\033[38;2;225;87;177m_\033[38;2;226;85;175m/ \033[38;2;228;83;171m/ \033[38;2;230;80;167m/\033[38;2;231;79;164m_\033[38;2;232;78;162m/ \033[38;2;234;75;158m/  \033[38;2;234;73;154m/ \033[38;2;227;78;158m_\033[38;2;223;81;160m_  \033[38;2;211;88;166m/ \033[38;2;204;93;170m/\033[38;2;200;95;172m_\033[38;2;196;98;174m/ \033[38;2;189;103;178m(\033[38;2;185;105;180m_\033[38;2;181;108;182m_  \033[38;2;170;115;188m) \033[38;2;162;120;192m/\033[38;2;158;122;194m_\033[38;2;155;125;196m/ \033[38;2;147;130;200m/ \033[38;2;139;135;204m/ \033[38;2;132;140;208m/ \033[38;2;124;145;212m/ \033[38;2;117;150;216m/\033[38;2;113;152;218m_\033[38;2;109;155;220m/ \033[38;2;101;159;224m/ \033[0m\n"
printf "\033[38;2;207;112;219m/\033[38;2;208;111;217m_\033[38;2;209;109;214m/\033[38;2;210;108;212m|\033[38;2;211;107;210m_\033[38;2;211;105;208m\\\\\033[38;2;212;104;206m_\033[38;2;213;103;204m_\033[38;2;214;102;202m_\033[38;2;215;100;200m_\033[38;2;216;99;198m/\033[38;2;217;98;196m\\\\\033[38;2;218;97;194m_\033[38;2;219;95;192m_\033[38;2;220;94;189m,\033[38;2;221;93;187m_\033[38;2;222;92;185m/\033[38;2;223;90;183m_\033[38;2;223;89;181m/\033[38;2;224;88;179m|\033[38;2;225;87;177m_\033[38;2;226;85;175m\\\\\033[38;2;227;84;173m_\033[38;2;228;83;171m_\033[38;2;229;81;169m_\033[38;2;230;80;167m_\033[38;2;231;79;164m/\033[38;2;232;78;162m\\\\\033[38;2;233;76;160m_\033[38;2;234;75;158m_\033[38;2;235;74;156m,\033[38;2;236;73;154m_\033[38;2;234;73;154m/  \033[38;2;223;81;160m/\033[38;2;219;83;162m_\033[38;2;215;86;164m/ \033[38;2;208;90;168m/\033[38;2;204;93;170m_\033[38;2;200;95;172m/\033[38;2;196;98;174m\\\\\033[38;2;192;100;176m_\033[38;2;189;103;178m_\033[38;2;185;105;180m_\033[38;2;181;108;182m_\033[38;2;177;110;184m/\033[38;2;173;113;186m_\033[38;2;170;115;188m_\033[38;2;166;118;190m_\033[38;2;162;120;192m_\033[38;2;158;122;194m/\033[38;2;155;125;196m\\\\\033[38;2;151;127;198m_\033[38;2;147;130;200m_\033[38;2;143;132;202m/\033[38;2;139;135;204m_\033[38;2;136;137;206m/\033[38;2;132;140;208m_\033[38;2;128;142;210m/ \033[38;2;120;147;214m/\033[38;2;117;150;216m_\033[38;2;113;152;218m/\033[38;2;109;155;220m\\\\\033[38;2;105;157;222m_\033[38;2;101;159;224m_\033[38;2;98;162;226m, \033[38;2;90;167;230m/  \033[0m\n"
printf "                                                                \033[38;2;98;162;226m/\033[38;2;94;164;228m_\033[38;2;90;167;230m_\033[38;2;86;169;232m_\033[38;2;83;172;234m_\033[38;2;79;174;236m/   \033[0m\n"

# Information System & Environnement
PY_VER=$(python --version 2>&1 || echo "Python 3.x")
echo -e "${DIM}┌─${NC} ${BOLD}XouXou Hosting${NC} ${DIM}• Environment Details${NC}"
echo -e "${DIM}│${NC}  ${BOLD}Python${NC}    : ${GREEN}${PY_VER}${NC}"
echo -e "${DIM}│${NC}  ${BOLD}Execution${NC} : ${CYAN}${PY_FILE}${NC}"
if [[ -d .git ]]; then
    GIT_BRANCH=$(git branch --show-current 2>/dev/null || echo "main")
    echo -e "${DIM}│${NC}  ${BOLD}Git Repo${NC}  : ${BLUE}Branch [${GIT_BRANCH}]${NC}"
fi
echo -e "${DIM}└─────────────────────────────────────────────────────────────${NC}\n"

# Mise a jour Git
if [[ -d .git ]] && [[ "${AUTO_UPDATE}" == "1" ]]; then
    echo -e "${YELLOW}⚡ [GIT]${NC} Synchronisation du dépôt..."
    git pull || echo -e "${RED}⚠️  [GIT]${NC} Échec de synchronisation."
fi

# Gestion des dépendances PIP
if [[ "${PIP_UPDATE}" == "1" ]]; then
    if [[ -n "${PY_PACKAGES}" ]]; then
        echo -e "${BLUE}📦 [PIP]${NC} Installation des paquets supplémentaires..."
        pip install --disable-pip-version-check --no-warn-script-location -U --prefix .local ${PY_PACKAGES} 2>&1 | grep -v -E "(Requirement already satisfied|^[[:space:]]*$)" || true
    fi
    if [[ -f "/home/container/${REQUIREMENTS_FILE}" ]]; then
        echo -e "${BLUE}📦 [PIP]${NC} Vérification des dépendances (${REQUIREMENTS_FILE})..."
        pip install --disable-pip-version-check --no-warn-script-location -U --prefix .local -r "${REQUIREMENTS_FILE}" 2>&1 | grep -v -E "(Requirement already satisfied|^[[:space:]]*$)" || true
        echo -e "${GREEN}✓ [PIP]${NC} Toutes les dépendances sont prêtes."
    fi
fi

# Lancement de l'application Python
echo -e "\n${GREEN}🚀 [START]${NC} Lancement de l'application ${BOLD}${PY_FILE}${NC}...\n"
exec /usr/local/bin/python "/home/container/${PY_FILE}"
